-- The backtest's statistics of the copies of its 975 picks (research 2026-10-11/12, last up to
-- 90 days): the allocator ranks a trader by them until its paper copy has closed trades enough.
CREATE TABLE IF NOT EXISTS backtest_stats (
    address      text    PRIMARY KEY,
    trips        integer NOT NULL,
    pnl          float8  NOT NULL,
    win_usd      float8  NOT NULL,
    loss_usd     float8  NOT NULL,
    max_dd_pct   float8  NOT NULL,
    pnl_sq       float8  NOT NULL,
    slip_bps     float8  NOT NULL,
    coins        jsonb   NOT NULL
);
ON CONFLICT (address) DO NOTHING;
